/* ---------- 3. EMPRESAS Y TARIFAS CORPORATIVAS ---------- */
INSERT INTO Empresa (ruc, razonSocial, contacto, telefono, correo, descuentoPorcentaje, facturacionDiferenciada, diasCredito)
SELECT v.ruc, v.razon, v.contacto, v.tel, v.correo, v.descuento, v.fact, v.credito
FROM (VALUES
      ('20511122233', N'Inversiones Pacífico S.A.C.', N'Rosa Cárdenas', '014441001', N'compras@pacifico.pe', 10, 1, 30),
      ('20522233344', N'Textiles Andinos E.I.R.L.', N'Mario Quispe', '014441002', N'admin@textilesandinos.pe', 8, 1, 15),
      ('20533344455', N'Transportes Inca S.A.', N'Lucía Paredes', '014441003', N'rrhh@transportesinca.pe', 10, 1, 30),
      ('20544455566', N'Agroexport del Norte S.A.C.', N'Jorge Salazar', '044441004', N'viajes@agronorte.pe', 12, 1, 45),
      ('20555566677', N'Consultores Lima Sur S.A.C.', N'Ana Ríos', '014441005', N'info@consultoreslimasur.pe', 7, 0, 0),
      ('20566677788', N'Minera Cerro Alto S.A.', N'Víctor Mendoza', '054441006', N'logistica@cerroalto.pe', 15, 1, 30),
      ('20577788899', N'Clínica San Gabriel S.A.', N'Carmen Silva', '014441007', N'compras@sangabriel.pe', 9, 1, 15),
      ('20588899900', N'Constructora Horizonte S.A.C.', N'Raúl Vargas', '014441008', N'obras@horizonte.pe', 12, 1, 30)
     ) AS v(ruc, razon, contacto, tel, correo, descuento, fact, credito)
WHERE NOT EXISTS (SELECT 1 FROM Empresa e WHERE e.ruc = v.ruc);
GO

INSERT INTO EmpresaTarifa (idEmpresa, idTipo, precioNoche)
SELECT e.idEmpresa, t.idTipo, CAST(t.tarifaBase * (1 - e.descuentoPorcentaje / 100.0) AS DECIMAL(10,2))
FROM Empresa e
JOIN TipoHabitacion t ON t.nombre IN (N'Simple', N'Doble', N'Matrimonial')
WHERE e.ruc IN ('20511122233', '20522233344', '20533344455', '20544455566', '20555566677', '20566677788', '20577788899', '20588899900')
  AND NOT EXISTS (SELECT 1 FROM EmpresaTarifa x WHERE x.idEmpresa = e.idEmpresa AND x.idTipo = t.idTipo);
GO

/* ---------- 4. SERVICIOS, PAQUETES, PROMOCIONES Y TEMPORADAS ---------- */
INSERT INTO ServicioAdicional (nombre, area, precio)
SELECT v.nombre, v.area, v.precio
FROM (VALUES
      (N'Desayuno a la habitación', 'RESTAURANTE', 48),
      (N'Minibar', 'RESTAURANTE', 25),
      (N'Cena romántica', 'RESTAURANTE', 150),
      (N'Lavado en seco (prenda)', 'LAVANDERIA', 22),
      (N'Masaje de pareja', 'SPA', 220),
      (N'Acceso a spa (día)', 'SPA', 80),
      (N'Traslado al aeropuerto VIP', 'TRANSPORTE', 110),
      (N'Tour por la ciudad', 'TRANSPORTE', 95),
      (N'Estacionamiento (día)', 'OTROS', 20),
      (N'Sala de reuniones (hora)', 'OTROS', 90)
     ) AS v(nombre, area, precio)
WHERE NOT EXISTS (SELECT 1 FROM ServicioAdicional s WHERE s.nombre = v.nombre);
GO

INSERT INTO Paquete (nombre, descripcion, noches, precio, idTipo)
SELECT v.nombre, v.descripcion, v.noches, v.precio, t.idTipo
FROM (VALUES
      (N'Fin de semana familiar', N'2 noches en habitación familiar con desayunos y un tour por la ciudad', 2, 780, N'Familiar'),
      (N'Luna de miel',           N'3 noches en suite con cena romántica, masaje de pareja y desayuno a la habitación', 3, 1350, N'Suite'),
      (N'Escapada corporativa',   N'2 noches en habitación doble con sala de reuniones y traslado', 2, 420, N'Doble')
     ) AS v(nombre, descripcion, noches, precio, tipo)
JOIN TipoHabitacion t ON t.nombre = v.tipo
WHERE NOT EXISTS (SELECT 1 FROM Paquete p WHERE p.nombre = v.nombre);
GO

INSERT INTO PaqueteServicio (idPaquete, idServicio, cantidad)
SELECT p.idPaquete, s.idServicio, v.cantidad
FROM (VALUES
      (N'Fin de semana familiar', N'Desayuno buffet', 4),
      (N'Fin de semana familiar', N'Tour por la ciudad', 1),
      (N'Luna de miel', N'Cena romántica', 1),
      (N'Luna de miel', N'Masaje de pareja', 1),
      (N'Luna de miel', N'Desayuno a la habitación', 3),
      (N'Escapada corporativa', N'Sala de reuniones (hora)', 2),
      (N'Escapada corporativa', N'Traslado aeropuerto', 1)
     ) AS v(paquete, servicio, cantidad)
JOIN Paquete p ON p.nombre = v.paquete
JOIN ServicioAdicional s ON s.nombre = v.servicio
WHERE NOT EXISTS (SELECT 1 FROM PaqueteServicio x WHERE x.idPaquete = p.idPaquete AND x.idServicio = s.idServicio);
GO

INSERT INTO Promocion (codigo, nombre, tipoDescuento, valor, fechaInicio, fechaFin, minNoches, idTipo)
SELECT v.codigo, v.nombre, v.tipoDescuento, v.valor, v.inicio, v.fin, v.minNoches, t.idTipo
FROM (VALUES
      ('SEMANA7',  N'7 noches o más: 7% de descuento', 'PORCENTAJE', 7,  '2026-01-01', '2027-12-31', 7, NULL),
      ('FAMILIA10',N'10% en habitaciones familiares',  'PORCENTAJE', 10, '2026-01-01', '2027-12-31', 2, N'Familiar'),
      ('CORP20',   N'S/ 20 por noche para corporativos','MONTO',     20, '2026-01-01', '2027-12-31', 1, NULL),
      ('PRIMAVERA',N'12% en temporada de primavera',   'PORCENTAJE', 12, '2026-09-01', '2026-11-30', 2, NULL),
      ('MATRI15',  N'15% en habitación matrimonial',   'PORCENTAJE', 15, '2026-01-01', '2027-12-31', 2, N'Matrimonial'),
      ('LUNAMIEL', N'S/ 100 por noche en suite',       'MONTO',      100,'2026-01-01', '2027-12-31', 2, N'Suite')
     ) AS v(codigo, nombre, tipoDescuento, valor, inicio, fin, minNoches, tipo)
LEFT JOIN TipoHabitacion t ON t.nombre = v.tipo
WHERE NOT EXISTS (SELECT 1 FROM Promocion p WHERE p.codigo = v.codigo);
GO

INSERT INTO Temporada (nombre, fechaInicio, fechaFin, factor)
SELECT v.nombre, v.inicio, v.fin, v.factor
FROM (VALUES
      (N'Temporada Baja 2027',        '2027-03-01', '2027-06-30', 0.90),
      (N'Temporada Media 2027',       '2027-07-01', '2027-12-14', 1.00),
      (N'Fiestas de Fin de Año 2027', '2027-12-15', '2028-01-05', 1.40)
     ) AS v(nombre, inicio, fin, factor)
WHERE NOT EXISTS (SELECT 1 FROM Temporada t WHERE t.nombre = v.nombre);
GO

