/* ---------- 9. SOLICITUDES ESPECIALES (huéspedes en casa) ---------- */
INSERT INTO SolicitudEspecial (idEstadia, descripcion, estado, fecha)
SELECT e.idEstadia, N'Almohadas adicionales', 'PENDIENTE', DATEADD(HOUR, -11, GETDATE())
FROM Estadia e JOIN Habitacion h ON h.idHabitacion = e.idHabitacion
WHERE h.numero = '405' AND e.estado = 'EN_CURSO'
  AND NOT EXISTS (SELECT 1 FROM SolicitudEspecial s WHERE s.idEstadia = e.idEstadia AND s.descripcion = N'Almohadas adicionales');
