/* ---------- 10. RESUMEN ---------- */
SELECT 'Usuarios' AS dato, COUNT(*) AS cantidad FROM Usuario
UNION ALL SELECT 'Usuarios de mantenimiento', COUNT(*) FROM Usuario u JOIN Rol r ON r.idRol = u.idRol WHERE r.nombre = N'Mantenimiento'
UNION ALL SELECT 'Habitaciones', COUNT(*) FROM Habitacion
UNION ALL SELECT 'Clientes', COUNT(*) FROM Cliente
UNION ALL SELECT 'Empresas', COUNT(*) FROM Empresa
UNION ALL SELECT 'Reservas', COUNT(*) FROM Reserva
UNION ALL SELECT 'Estadías', COUNT(*) FROM Estadia
UNION ALL SELECT 'Facturas', COUNT(*) FROM Factura
UNION ALL SELECT 'Consumos', COUNT(*) FROM ConsumoServicio
UNION ALL SELECT 'Encuestas', COUNT(*) FROM EncuestaSatisfaccion
UNION ALL SELECT 'Tareas de limpieza', COUNT(*) FROM TareaLimpieza
UNION ALL SELECT 'Reportes de mantenimiento', COUNT(*) FROM Mantenimiento;
GO
PRINT 'Datos adicionales cargados correctamente.';
